<?php declare(strict_types=1);
require_once __DIR__.'/../../../src/Finance/Invoices/InvoiceIntakeList.php';
require __DIR__.'/../../../src/Web/invoice-overview-labels.php';
$inboxList=$inboxCatalogue;$inboxYears=$inboxList['years'];$inboxYear=$inboxList['year'];
$inboxRoute=['view'=>'finance','tab'=>'inbox','status'=>$inboxFilter,'inbox_q'=>$inboxList['query'],'inbox_year'=>$inboxYear];
?>
<form method="get" class="intake-toolbar" data-invoice-overview-search role="search" aria-label="<?=e($invoiceOverviewText('Rechnungen suchen'))?>">
<?=hidden('view','finance').hidden('tab','inbox').hidden('status',$inboxFilter)?>
<label><?=e($invoiceOverviewText('Rechnung suchen'))?><input class="form-control" type="search" name="inbox_q" maxlength="300" value="<?=e($inboxList['query'])?>" placeholder="<?=e($invoiceOverviewText('Titel, Dateiname oder Absender'))?>"></label>
<label><?=e($invoiceOverviewText('Belegjahr'))?><select class="form-control" name="inbox_year"><option value=""><?=e($invoiceOverviewText('Alle Jahre'))?></option><?php if($inboxYear!==''&&!isset($inboxYears[$inboxYear])):?><option value="<?=e($inboxYear)?>" selected><?=e($inboxYear)?> · <?=e($invoiceOverviewText('Keine Rechnungen in diesem Jahr'))?></option><?php endif;?><?php foreach($inboxYears as$year):?><option value="<?=e($year)?>" <?=$inboxYear===(string)$year?'selected':''?>><?=e($year)?></option><?php endforeach;?></select></label><button class="btn btn-solid theme-primary"><?=e($invoiceOverviewText('Suchen'))?></button>
<?php if($inboxList['query']!==''||$inboxYear!==''):?><a class="btn btn-outline" data-invoice-overview-reset href="<?=e(url(['view'=>'finance','tab'=>'inbox','status'=>$inboxFilter]))?>"><?=e($invoiceOverviewText('Suche zurücksetzen'))?></a><?php endif;?>
</form><p class="intake-count" data-invoice-overview-count role="status"><?=e($invoiceOverviewText($inboxList['total']===1?'{count} Rechnung':'{count} Rechnungen',['count'=>$inboxList['total']]))?><?php if($inboxList['total']):?> · <?=e($invoiceOverviewText('{first}–{last} angezeigt · neueste zuerst',['first'=>$inboxList['first'],'last'=>$inboxList['last']]))?><?php endif;?></p>
<?php if(!$inboxList['rows']):?><p data-invoice-overview-empty><?=e($invoiceOverviewText($inboxList['query']!==''||$inboxYear!==''?'Keine passende Rechnung gefunden. Ändern Sie die Suche oder wählen Sie alle Jahre.':'In dieser Ansicht liegen keine Rechnungen.'))?></p><?php endif;?>
<div class="intake-list"><?php foreach($inboxList['rows']as$incoming):?><article class="intake-row" data-invoice-intake-summary><div><h3><?=e($incoming['title'])?></h3><p><?=e(dateDe($incoming['document_date']))?> · <?=e($inboxLabels[$incoming['inbox_status']])?><?php if(array_filter($incoming['links'],fn($link)=>$link['source_type']==='item')):?> · <?=e($invoiceOverviewText('Inventar verknüpft'))?><?php endif;?></p><p><?=e($incoming['mail_origins']?$invoiceOverviewText('E-Mail von {sender}',['sender'=>$incoming['mail_origins'][0]['sender']]):$invoiceOverviewText('Manuell hochgeladen'))?></p></div><a class="btn btn-solid theme-primary button <?=$incoming['inbox_status']==='open'?'':'secondary'?>" href="<?=e(url($inboxRoute+['inbox_page'=>$inboxList['page'],'inbox_doc'=>$incoming['id']]))?>"><?=e($invoiceOverviewText($incoming['inbox_status']==='open'?'Prüfen und zuordnen':'Rechnung öffnen'))?></a></article><?php endforeach;?></div>
<?php if($inboxList['pages']>1):?><nav class="intake-pagination" data-invoice-overview-pages aria-label="<?=e($invoiceOverviewText('Rechnungsseiten'))?>"><?php if($inboxList['page']>1):?><a class="btn btn-outline theme-secondary button secondary" rel="prev" href="<?=e(url($inboxRoute+['inbox_page'=>$inboxList['page']-1]))?>">← <?=e($invoiceOverviewText('Zurück'))?></a><?php endif;?><span><?=e($invoiceOverviewText('Seite {page} von {pages}',['page'=>$inboxList['page'],'pages'=>$inboxList['pages']]))?></span><?php if($inboxList['page']<$inboxList['pages']):?><a class="btn btn-outline theme-secondary button secondary" rel="next" href="<?=e(url($inboxRoute+['inbox_page'=>$inboxList['page']+1]))?>"><?=e($invoiceOverviewText('Weiter'))?> →</a><?php endif;?></nav>
<form method="get" class="intake-toolbar" data-intake-page><?php foreach($inboxRoute as$key=>$value)echo hidden($key,$value);?><label><?=e($invoiceOverviewText('Rechnungsseite'))?><input class="form-control" type="number" name="inbox_page" min="1" max="<?=$inboxList['pages']?>" value="<?=$inboxList['page']?>" required></label><button class="btn btn-outline theme-secondary"><?=e($invoiceOverviewText('Seite öffnen'))?></button></form><?php endif;?>
